ssize_t prepare_single_iovec(struct kiocb *kiocb, int rw, char __user *buf,
                             unsigned long *nr_segs, struct iovec *iovec)
{
    ssize_t len = kiocb->ki_remaining;

    if (len > MAX_RW_COUNT)
        len = MAX_RW_COUNT;

    if (rw == READ) {
        if (!access_ok(buf, len))
            return -EFAULT;
    } else {
        if (!access_ok((void __user *)buf, len))
            return -EFAULT;
    }

    iovec->iov_base = buf;
    iovec->iov_len = len;
    *nr_segs = 1;
    return 0;
}

ssize_t prepare_iovec(struct kiocb *kiocb, int rw, char __user *buf,
                      unsigned long *nr_segs, struct iovec *iovec)
{
    ssize_t len = kiocb->ki_remaining;

    if (len <= 0)
        return -EFAULT;

    if (len > MAX_RW_COUNT)
        len = MAX_RW_COUNT;

    if (rw == WRITE) {
        if (!access_ok(VERIFY_READ, buf, len))
            return -EFAULT;
    } else {
        if (!access_ok(VERIFY_WRITE, buf, len))
            return -EFAULT;
    }

    *nr_segs = 1;
    iovec->iov_base = buf;
    iovec->iov_len = len;

    return 0;
}

ssize_t prepare_iovec(struct kiocb *kiocb, int rw, char __user *buf,
                      unsigned long *nr_segs, struct iovec *iovec)
{
    ssize_t len = kiocb->ki_nbytes;

    if (len > SSIZE_MAX)
        return -EFAULT;

    if (!access_ok(buf, len))
        return -EFAULT;

    iovec->iov_base = buf;
    iovec->iov_len = len;
    *nr_segs = 1;

    return 0;
}

